SELECT situation_dashboard_instance.*, situation_dashboard_attribute.scheme_name as scheme_name
FROM situation_dashboard_instance left join situation_dashboard_attribute on
situation_dashboard_instance.attribute_id = situation_dashboard_attribute.resource_id
WHERE 1 = 1

    AND name like concat("%", #{situationPublishInstanceFilterReq.name}, "%")


    AND category = #{situationPublishInstanceFilterReq.category}


    AND situation_dashboard_attribute.level in

        #{level}



    AND situation_dashboard_instance.update_time > #{situationPublishInstanceFilterReq.startTime}


    AND situation_dashboard_instance.update_time < #{situationPublishInstanceFilterReq.endTime}


    AND status = #{situationPublishInstanceFilterReq.status}




            AND replay_mode = #{situationPublishInstanceFilterReq.replayMode}


            AND replay_mode != 0




    AND replay_mode = 0

ORDER BY

    sub_range_id asc,

create_time DESC

SELECT attribute_id FROM situation_dashboard_instance


        resource_id in

            #{resourceId}

SELECT * FROM situation_dashboard_instance

    status = 2
    and xd = 1

        and task_id = #{taskId}


        and subject_id = #{subjectId}

SELECT resource_id FROM situation_dashboard_instance

    xd = 1

        and scheme_id = #{schemeId}

SELECT * FROM situation_dashboard_instance

    status = 2

        and task_id = #{taskId}


        and subject_id = #{subjectId}

SELECT * FROM situation_dashboard_instance

    xd = 1
    and scheme_id = #{schemeId}

select resource_id
from situation_dashboard_instance

    subject_id = #{subjectId}
    and task_id = #{taskId}
